SELECT vm.activity__active_date__day::date AS day, vm.value AS habits_completed, ao.value AS app_opens
FROM (
  SELECT activity__active_date__day, value FROM (
    SELECT activity__active_date__day, value FROM (
      -- value_moments by day for last_week
      SELECT activity__active_date__day, value
      FROM query_result_vm
    )
  )
) vm
JOIN (
  SELECT activity__active_date__day, value FROM query_result_ao
) ao
ON vm.activity__active_date__day = ao.activity__active_date__day
ORDER BY day;

SELECT SUM(value) AS total_signups
FROM (
  SELECT value
  FROM "query_metric_new_signups_monthly"
  WHERE user__region = 'APAC' AND metric_time >= '2026-04-01' AND metric_time <= '2026-06-30'
) t;
